[{"order":1,"type":"heading","text":"Retrofit, OkHttp Interceptors, and Certificate Pinning in Android"},{"order":2,"type":"paragraph","text":"Securing network communication in modern Android applications is critical. Retrofit relies on OkHttp as its underlying HTTP client, which provides powerful extension points like Interceptors and Certificate Pinning to modify requests and secure transport layers against Man-in-the-Middle (MitM) attacks."},{"order":3,"type":"subheading","text":"1. Adding Dependencies"},{"order":4,"type":"paragraph","text":"Add the required Retrofit and OkHttp libraries to your module-level build.gradle.kts file."},{"order":5,"type":"code","text":"implementation("com.squareup.retrofit2:retrofit:2.9.0")
implementation("com.squareup.retrofit2:converter-gson:2.9.0")
implementation("com.squareup.okhttp3:okhttp:4.11.0")
implementation("com.squareup.okhttp3:logging-interceptor:4.11.0")"},{"order":6,"type":"subheading","text":"2. Creating Custom OkHttp Interceptors"},{"order":7,"type":"paragraph","text":"Interceptors can monitor, rewrite, and retry calls. A common use case is adding authorization headers dynamically to every outgoing API request."},{"order":8,"type":"code","text":"class AuthInterceptor(private val tokenManager: TokenManager) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val originalRequest = chain.request()
        val token = tokenManager.getToken()

        val modifiedRequest = if (!token.isNullOrEmpty()) {
            originalRequest.newBuilder()
                .header("Authorization", "Bearer $token")
                .build()
        } else {
            originalRequest
        }

        return chain.proceed(modifiedRequest)
    }
}"},{"order":9,"type":"subheading","text":"3. Implementing Certificate Pinning"},{"order":10,"type":"paragraph","text":"Certificate pinning restricts which certificates are trusted for a specific domain, protecting your app against rogue certificate authorities. You configure this using CertificatePinner."},{"order":11,"type":"code","text":"val certificatePinner = CertificatePinner.Builder()
    .add("api.yourdomain.com", "sha256/AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=")
    .build()"},{"order":12,"type":"subheading","text":"4. Integrating OkHttp with Retrofit"},{"order":13,"type":"paragraph","text":"Combine the interceptors, logging, and certificate pinner into an OkHttpClient builder, and then pass it to your Retrofit instance."},{"order":14,"type":"code","text":"val loggingInterceptor = HttpLoggingInterceptor().apply {
    level = HttpLoggingInterceptor.Level.BODY
}

val okHttpClient = OkHttpClient.Builder()
    .addInterceptor(AuthInterceptor(tokenManager))
    .addInterceptor(loggingInterceptor)
    .certificatePinner(certificatePinner)
    .connectTimeout(30, TimeUnit.SECONDS)
    .readTimeout(30, TimeUnit.SECONDS)
    .build()

val retrofit = Retrofit.Builder()
    .baseUrl("https://api.yourdomain.com/")
    .client(okHttpClient)
    .addConverterFactory(GsonConverterFactory.create())
    .build()"},{"order":15,"type":"subheading","text":"Best Practices"},{"order":16,"type":"bullet_point","text":"Always provide backup pins in your CertificatePinner to avoid app outages during server certificate rotations."},{"order":17,"type":"bullet_point","text":"Disable the HttpLoggingInterceptor in production builds to prevent sensitive data leakage in the Logcat."},{"order":18,"type":"bullet_point","text":"Order matters: place logging interceptors last if you want to log headers added by previous interceptors."}]
